{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table eggozdb.maplemonk.Franchise_Sales_Tracker as select st.date,tt.dealer_name,st.code, avg(tt.target_revenue) target_revenue, tt.dsr_name,tt.so_name, sum(st.revenue) revenue, sum(st.dsr_sales) dsr_sales,sum(st.promoter_sales) promoter_sales,st.bill_count,st.tertiary_bill_count,st.uob, sum(st.eggs_sold) eggs_sold, sum(dsr_eggs_sold) dsr_eggs_sold, sum(promoter_eggs_sold) promoter_eggs_sold, Trays, CASE WHEN TARGET_REVENUE > 0 THEN ROUND(SUM(REVENUE) / AVG(TARGET_REVENUE) * 100, 2) ELSE \'0\' END as Sales_achivement, COUNT(DISTINCT st.date) OVER () AS total_days, DAY(MAX(st.date)) AS day_of_max_date from bi_franchise_sales_tracker_targets tt left join (select coalesce(ps.retailer_name,ts.dealer_name,crm.code) as code,dsr_name,so_name,sr_name, coalesce(ps.date,ts.delivery_date,crm.crm_date) date,ps.bill_count,ts.tertiary_bill_count,ts.uob, ps.revenue,ts.sku_sale as DSR_sales,crm.crm_sale as Promoter_Sales, ps.eggs_sold,ts.eggs_sold DSR_eggs_Sold,crm.eggs_sold as Promoter_eggs_sold, (ps.eggs_sold)/25 as Trays from (select retailer_name,date,sum(revenue) revenue,sum(eggs_sold) eggs_sold ,so.dsr_name,so.so_name,so.sr_name, count(distinct(concat(retailer_name,date))) bill_count from eggozdb.maplemonk.primary_and_secondary_sku ps left join eggozdb.maplemonk.beat_tagging so on ps.retailer_name=so.code and ps.area_classification = so.area_classification group by retailer_name,date,so.dsr_name,so.so_name,so.sr_name ) ps full outer join (select dealer_name, delivery_date,sum(sku_sale) sku_sale,sum(eggs_sold) eggs_sold, count(distinct(concat(dealer_name,delivery_date))) tertiary_bill_count, count(distinct(concat(dealer_name,code))) uob from tertiary_sales group by dealer_name,delivery_date ) ts on ps.retailer_name=ts.dealer_name and ps.date=ts.delivery_date full outer join (select code,crm_date,sum(crm_sale)crm_sale,sum(crm_eggs_sold) eggs_sold from crm_overview group by code,crm_date ) crm on ts.dealer_name = crm.code and ts.delivery_date = crm.crm_date ) st on tt.Dealer_Code=SPLIT_PART(st.code, \'*\', 1) and tt.month = month(st.date) and tt.year = year(st.date) group by tt.dealer_name,st.code,tt.dsr_name,tt.so_name, st.date,Trays,st.bill_count,st.tertiary_bill_count,st.uob,tt.TARGET_REVENUE ; create or replace table eggozdb.maplemonk.CRM_overview as SELECT tt.*, CASE WHEN COUNT(DISTINCT DATE_TRUNC(\'MONTH\', CRM_date)) OVER (PARTITION BY Customers, code) >= 2 THEN \'Repeated\' ELSE \'Non-Repeated\' END AS status, COUNT(DISTINCT Customers) OVER (PARTITION BY first_month, code) AS first_month_customer_count, COUNT(DISTINCT DATE_TRUNC(\'MONTH\', CRM_date)) OVER (PARTITION BY Customers, code) AS months_billed, DATEDIFF( MONTH, MIN(first_month) OVER (PARTITION BY Customers, code), (SELECT MAX(DATE_TRUNC(\'MONTH\', CAST(TIMESTAMPADD(minute,660,modified_at) AS DATE))) FROM my_sql_order_cmsorder) ) + 1 AS total_months, ROUND( 100.0 * COUNT(DISTINCT DATE_TRUNC(\'MONTH\', CRM_date)) OVER (PARTITION BY Customers, code) / NULLIF( DATEDIFF( MONTH, MIN(first_month) OVER (PARTITION BY Customers, code), (SELECT MAX(DATE_TRUNC(\'MONTH\', CAST(TIMESTAMPADD(minute,660,modified_at) AS DATE))) FROM my_sql_order_cmsorder) ) + 1, 0 ), 2 ) AS retention_ratio FROM ( SELECT oc.id AS order_id, rr.id, rr.code, CAST(TIMESTAMPADD(minute,660,oc.modified_at) AS DATE) AS CRM_date, MIN(DATE_TRUNC(\'MONTH\', CAST(TIMESTAMPADD(minute,660,oc.modified_at) AS DATE))) OVER (PARTITION BY rc.id, rr.code) AS first_month, CONCAT(rc.id,\'-\',rc.name) AS Customers, rc.loyalty_points, oc.payable_amount, ocl.single_sku_rate AS CRM_single_sku_rate, ocl.single_sku_rate*ocl.quantity AS CRM_sale, ocl.mrp, ocl.quantity AS CRM_Quantity, SUM(pp.SKU_Count*ocl.quantity) AS CRM_eggs_sold, CONCAT(pp.sku_count,pp.short_name) AS CRM_SKU, pcp.product_name AS Redeem_SKU, SUM(olrl.quantity) AS Gift_quantity, SUM(olr.point_added) AS Points_added, SUM(olr.point_subtracted) AS Points_sub, SUM(olr.point_subtracted) * 1.0/NULLIF(SUM(olr.point_added), 0) AS Redemtion_Ratio, SUM(olr.point_subtracted) OVER (PARTITION BY rc.name) * 1.0/NULLIF(SUM(olr.point_added) OVER (PARTITION BY rc.name), 0) AS customer_Redemtion_Ratio FROM my_sql_order_cmsorder oc LEFT JOIN my_sql_retailer_retailer rr ON oc.retailer_id = rr.id LEFT JOIN my_sql_order_cmsorderline ocl ON oc.id=ocl.cms_order_id LEFT JOIN my_sql_product_product pp ON ocl.product_id=pp.id LEFT JOIN my_sql_retailer_cmscustomer rc ON oc.customer_id = rc.id LEFT JOIN my_sql_order_cmsloyaltyredeem olr ON oc.id = olr.cms_order_id AND olr.customer_id = oc.customer_id LEFT JOIN my_sql_order_cmsloyaltyredeemline olrl ON olr.id = olrl.cms_loyalty_redeem_id LEFT JOIN my_sql_product_cmsgiftproduct pcp ON olrl.gift_product_id = pcp.id GROUP BY rr.id, oc.id, rr.code, oc.modified_at, rc.id, rc.name, rc.loyalty_points, ocl.single_sku_rate, oc.payable_amount, pp.sku_count, pp.short_name, pcp.product_name, ocl.mrp, ocl.quantity, olr.point_subtracted, olr.point_added ) tt",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from EGGOZDB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            